[BurstCompile]
struct NeighboursJob : IJobParallelFor
{
    [ReadOnly] public NativeArray<float3> positions;
    public NativeArray<int> counts;

    public void Execute(int i)
    {
        // scratch memory of this job: released when the job ends
        var near = new NativeList<int>(16, Allocator.Temp);
        FindNear(positions, i, ref near);
        counts[i] = near.Length;
    }
}

