NativeList<int> hits;     // reused every frame
JobHandle handle;

void Awake() => hits = new NativeList<int>(1024, Allocator.Persistent);

void Update()
{
    hits.Clear();                         // length 0, the memory stays
    handle = new HitJob { hits = hits }.Schedule();
    JobHandle.ScheduleBatchedJobs();
}

void LateUpdate() => handle.Complete();

void OnDestroy()
{
    handle.Complete();                    // a job may still use the buffer
    if (hits.IsCreated) hits.Dispose();
}

