public class Boids : MonoBehaviour
{
    public int count = 10000;
    NativeArray<float3> velocities;
    JobHandle handle;

    void Awake()
    {
        velocities = new NativeArray<float3>(count, Allocator.Persistent);   // once
    }

    void Update()
    {
        handle = new SteerJob { velocities = velocities }.Schedule(count, 64);
        JobHandle.ScheduleBatchedJobs();
    }

    void LateUpdate()
    {
        handle.Complete();
        Apply(velocities);
    }

    void OnDestroy()
    {
        handle.Complete();                        // this frame's job may still run
        if (velocities.IsCreated) velocities.Dispose();
    }
}

